// Oracle generator for src/rustc_parse/parser/pat_stmt_oracle.json (lane parser-pat-stmt).
// Usage: bun gen.ts <cases.json> <out.json>
// Each case {name, kind, src} is wrapped into t.rs, compiled with
//   rustc +nightly-2026-10-11 -Zunpretty=ast-tree -Zui-testing --edition 2024 t.rs
// and the relevant subtree of the ast-tree dump is extracted (see `extract`).
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

type Kind = "let" | "for" | "closure" | "block" | "stmt";
interface Case { name: string; kind: Kind; src: string }

export function wrap(kind: Kind, src: string): string {
  switch (kind) {
    case "let": return `fn f() { let ${src}; }\n`;
    case "for": return `fn f() { for ${src} in x {} }\n`;
    case "closure": return `fn f() { |${src}| (); }\n`;
    case "block": return `fn f() {\n${src}\n}\n`;
    case "stmt": return `fn f() { ${src} }\n`;
  }
}

/** The subtree: pattern kinds -> the first `pat: Pat {..}` (Local.pat / ForLoop.pat / Param.pat);
 *  block -> the fn's `body: Some(Block {..})`; stmt -> the first element of the body's `stmts`.
 *  Taken from its opening line to the closing line at the same indentation, dedented. */
function extract(kind: Kind, tree: string): string | null {
  const lines = tree.split("\n");
  let start = -1;
  let ind = "";
  let first = "";
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i]!;
    let m: RegExpMatchArray | null;
    if ((kind === "let" || kind === "for" || kind === "closure") && (m = l.match(/^( *)pat: Pat \{$/))) {
      start = i; ind = m[1]!; first = "Pat {"; break;
    }
    if (kind === "block" && (m = l.match(/^( *)body: Some\($/)) && lines[i + 1] === `${m[1]}    Block {`) {
      start = i + 1; ind = `${m[1]}    `; first = "Block {"; break;
    }
    if (kind === "stmt" && (m = l.match(/^( *)stmts: \[$/)) && lines[i + 1] === `${m[1]}    Stmt {`) {
      start = i + 1; ind = `${m[1]}    `; first = "Stmt {"; break;
    }
  }
  if (start < 0) return null;
  const out = [first];
  for (let i = start + 1; i < lines.length; i++) {
    const l = lines[i]!;
    if (l === `${ind}},`) { out.push("}"); return out.join("\n"); }
    if (!l.startsWith(ind)) throw new Error(`bad indentation at line ${i}`);
    out.push(l.slice(ind.length));
  }
  throw new Error("unterminated subtree");
}

/** Driver-only trailer, not produced by the parser: `error: aborting due to ..`, the warning count and
 *  the `rustc --explain` pointers (each a paragraph ending in a blank line, or the final line). */
function strip_trailer(stderr: string): string {
  const trailer =
    /(?:error: aborting due to [^\n]*\n\n|warning: [0-9]+ warnings? emitted\n\n|Some errors have detailed explanations: [^\n]*\n|For more information about (?:this error|an error), try `rustc --explain [^`]*`\.\n)+$/;
  return stderr.replace(trailer, "");
}

if (import.meta.main) {
  const [casesPath, outPath] = process.argv.slice(2);
  const cases = JSON.parse(readFileSync(casesPath!, "utf8")) as Case[];
  const dir = mkdtempSync(join(tmpdir(), "pat-stmt-"));
  const version = execFileSync("rustc", ["+nightly-2026-10-11", "-vV"], { encoding: "utf8" }).split("\n")[0];
  const out = [];
  for (const c of cases) {
    const file = join(dir, "t.rs");
    writeFileSync(file, wrap(c.kind, c.src));
    const r = spawnSync("rustc", ["+nightly-2026-10-11", "-Zunpretty=ast-tree", "-Zui-testing", "--edition", "2024", "t.rs"], { cwd: dir, encoding: "utf8" });
    out.push({ ...c, tree: extract(c.kind, r.stdout), stderr: strip_trailer(r.stderr), exit: r.status });
  }
  writeFileSync(outPath!, JSON.stringify({ version, cases: out }, null, 1) + "\n");
  console.log(`${out.length} cases -> ${outPath}`);
}

